    .replace(/(^|[^\w*])[*_]([^*_\n]+)[*_](?=[^\w*]|$)/g, '$1$2') // italics
    .replace(/`([^`]*)`/g, '$1')
    .replace(/[*_]{2,}/g, '')
    .trim()).filter(Boolean);
